type Factory func(cfg Config) (Shape, error)

var (
    mu       sync.RWMutex
    registry = map[string]Factory{}
)

func Register(name string, f Factory) {
    mu.Lock()
    defer mu.Unlock()
    if _, dup := registry[name]; dup { panic("factory: duplicate " + name) }
    registry[name] = f
}
